package com.bidx.util;
import javax.xml.XMLConstants; import javax.xml.parsers.*; import javax.xml.transform.*; import javax.xml.transform.dom.DOMSource; import javax.xml.transform.stream.StreamResult; import org.w3c.dom.*; import java.nio.file.*; import java.io.*;
/** Safe, atomic XML document storage. Callers synchronize multi-file transactions. */
public final class XmlStore { private XmlStore(){} public static Document load(Path path,String root){try {DocumentBuilderFactory f=DocumentBuilderFactory.newInstance(); f.setFeature(XMLConstants.FEATURE_SECURE_PROCESSING,true); f.setFeature("http://apache.org/xml/features/disallow-doctype-decl",true); f.setExpandEntityReferences(false); DocumentBuilder b=f.newDocumentBuilder(); if(!Files.exists(path)){Document d=b.newDocument();d.appendChild(d.createElement(root));return d;} return b.parse(path.toFile());}catch(Exception e){throw new IllegalStateException("Unable to read "+path.getFileName(),e);}} public static void save(Document d,Path path){try {Files.createDirectories(path.getParent()); Path tmp=Files.createTempFile(path.getParent(),path.getFileName().toString(),".tmp"); Transformer t=TransformerFactory.newInstance().newTransformer();t.setOutputProperty(OutputKeys.INDENT,"yes");t.setOutputProperty(OutputKeys.ENCODING,"UTF-8");t.transform(new DOMSource(d),new StreamResult(tmp.toFile())); try{Files.move(tmp,path,StandardCopyOption.ATOMIC_MOVE,StandardCopyOption.REPLACE_EXISTING);}catch(AtomicMoveNotSupportedException e){Files.move(tmp,path,StandardCopyOption.REPLACE_EXISTING);}}catch(Exception e){throw new IllegalStateException("Unable to save "+path.getFileName(),e);}} public static String text(Element e,String n){NodeList l=e.getElementsByTagName(n); return l.getLength()==0?"":l.item(0).getTextContent();} public static void put(Document d,Element e,String n,Object v){Element x=d.createElement(n);x.setTextContent(v==null?"":v.toString());e.appendChild(x);} }
